def parse_price(s: str) -> float:
    s = s.strip()
    if not s or not s[0].isdigit() and s[0] != '\$':
        return 0.0

    # Remove currency symbol and commas
    s = s[1:].replace(',', '')

    # Split into whole and decimal parts
    if '.' in s:
        whole, decimal = s.split('.', 1)
        decimal = decimal.ljust(2, '0')[:2]
    else:
        whole = s
        decimal = '00'

    # Handle cases like '100' vs '100.0'
    if len(whole) == 0:
        return 0.0

    # Convert to float
    return float(f"{whole}.{decimal}")

